    "keyFindings": [
      "The data were analyzed with the Pearson Product Moment Correlation.",
      "The analysis results showed a significant correlation between post-traumatic growth and coping (r = .523; p < .01).",
      "In addition, coping ways that correlated with post-traumatic growth were seeking for social support (r = .545), distancing (r = .315), self-control and accepting (r=.274), while confronting and escape did not have a correlation with post-traumatic growth"
    ],
