    "abstractSummaryId": "Due to age-related changes, the elderly are prone to psychological problems, such as anxiety and stress, and mental disorder, such as depression. This study aimed to analyze the influence of anxiety and stress on depression in elderly living in the nursing home. This cross-sectional study involved 145 elderly in a private nursing home in Surabaya, Indonesia. Hamilton Anxiety Rating Scale (HARS), Suan Prung Stress Test - 20 (SPST-20), and Geriatric Depression Scale (GDS) was used for collecting data. Linear and ordinal regression tests were used in data analysis (α<0.05). Results showed that the majority was ol...",
