    "abstractSummaryId": "Amidst the social-cultural predominance of male ulama in the religious context, female ulama play important roles and yet are often trapped in life-role complexity and gender bias, as they have a responsibility in both the domestic and public domains. This study aims to explore the meaning of the experience of gratitude among female ulama based on the perspective of positive psychology, with reference to the PERMA (Positive emotion, Engagement, Relationship, Meaning, and Accomplishment) model, with further interpretation of gratitude (shukr) from Sufi psychology. Using a qualitative (phenomenological) approach...",
