      "Hasil menunjukkan adanya faktor psikologis, yaitu lemahnya faktor protektif pada partisipan yang memengaruhi perilaku bunuh diri, sekaligus menunjukan bahwa perilaku bunuh diri bukan disebabkan oleh munculnya Pulung yang tidak dapat dicegah sebagaimana diya...",
