    "abstractSummaryId": "Peer support has been highlighted as an important factor in the mental health of Indonesian migrant workers abroad. Although many studies have investigated spiritual well-being and coping strategies, few have investigated the role of these as mediating variables. This study aims to determine the direct and indirect influences of peer support on mental health through the spiritual well-being and coping strategies of Indonesian migrant workers living abroad. The research participants were 183 Indonesian migrant workers based overseas. The sampling technique employed was convenience sampling. The data collection...",
