    "abstractSummaryId": "Narapidana menjadi salah satu kelompok rentan yang mengalami permasalahan psikologis. Kondisi di dalam Lapas, terbatasnya aktivitas, dan terampasnya kebebasan memunculkan permasalahan psikologis di dalam Lapas, yang mempengaruhi rendahnya makna hidup. Makna hidup yang rendah dapat memunculkan adanya penilaian yang keliru pada kondisi narapidana penyalahgunaan narkotika. Narapidana dapat memiliki penilaian bahwa menggunakan narkotika dan perilaku kecanduan narkotika menjadi satu-satunya aspek positif dalam kehidupannya. Penilaian yang keliru ini kemudian dapat mengarahkan narapidana untuk memunculkan perilaku y...",
