    "abstractSummaryId": "Schools in Spain were closed in March 2020 to prevent the spread of COVID-19. In September 2020 most schools and universities in Spain reopened and teachers felt great uncertainty due to this unprecedented situation. Teachers have accumulated psychological symptoms since the beginning of the pandemic. During the lockdown they had to introduce online teaching and in view of the reopening of schools they have shown great concern for the new unprecedented teaching situation. The present study aims to measure the symptomatology shown by teaching staff in the Basque Autonomous Community at the time when schools wer...",
