    "abstractSummaryId": "The health benefits of regular physical activity and aerobic exercise are undisputed in the literature. The present series of pilot studies had two major objectives: a) examine mental health, well-being, and regular physical activity of university students and b) explore the potential health benefits of short-term aerobic exercise on university students in an online and a laboratory study. Mental health and well-being were measured before (Time 1, T1) and after (Time 2, T2) a six-week (online study) and two-week (laboratory study) low- to moderate-intensity aerobic exercise intervention. Mental health and well...",
