      "The present results confirm that there is a relationship between regular physical activity, cardiovascular fitness, mental health, and well-being among university students.",
      "They support the hypothesis that short-term aerobic exercise interventions can act as buffer against depression and perceived stress in university students after six weeks of aerobic exercise of low to moderate intensity."
