    "abstractSummaryId": "Depression is a disabling illness which increases the risk of suicide. The COVID-19 pandemic has led to a rise in fear, anxiety, stress and depression among the population: of these, university undergraduates from countries severely affected by COVID-19 are some of the most vulnerable of all, as they face strict lockdown measures and have fewer resources to cope with it. The aim of this study was to analyze the levels of fear of COVID-19, stress, anxiety and depression during lockdown among undergraduates from Ecuador and to test these possible predictors of depression using a model taken from our study of the...",
