      "This study adds to reports on poor mental health during lockdown and identifies lifestyle restrictions and changes to health behaviors which may, to some extent, be responsible for higher negative mood.",
      "Our data suggests that it is advisable to maintain or improve health behaviors during pandemic-associated restrictions."
