    "abstractSummaryId": "Objective Mindfulness disposition is associated with various psychological factors and prevents emotional distress in chronic diseases. In the present study, we analyzed the key role of mindfulness dispositions in protecting the individual against psychological distress consequent to COVID-19 social distancing and quarantining. Methods An online survey was launched on March 13, 2020, with 6,412 responses by April 6, 2020. Socio-demographic information, exposure to the pandemic, and quarantining were assessed together with psychological distress and mindfulness disposition. Multivariate linear regression analys...",
