    "abstractSummaryId": "The worldwide pandemic situation caused by coronavirus disease 2019 (COVID-19) has led to a state of confinement of the population, which has caused, following consulted research, an increase in stress. Faced with this situation, the Spanish university not only had to adapt to the changes derived from the causes of the pandemic but also had to face a new methodological model-e-learning teaching-for which not all teachers and students were prepared. This could cause an increase in stress due to the uncertainty caused by this time of change. This research analyzes the relationship between perceived self-efficacy...",
    "methodology": "Penelitian Empiris Psikologi (Lihat detail desain pada artikel sumber)",
    "sampleContext": "Detail jumlah & karakteristik partisipan tercantum lengkap pada teks penuh artikel DOI",
    "keyFindings": [
      "The results indicated that there was an inversely proportional relationship between anxiety and self-efficacy; men showed the highest perception of self-efficacy, while women had higher scores in TA and SA; the latter was accentuated in cases when a relativ...",
      "To conclude, students who show a higher level of anxiety (TA and SA) express more negative emotions and also perceive themselves with less academic self-efficacy.",
      "Therefore, a stressful situation (pandemic and confinement) together with a critical event (illness and death of a relative/friend due to COVID-19) increases anxiety levels and influences the perception of academic self-efficacy."
    ],
