    "abstractSummaryId": "Spain has been in a state of emergency since 14th March due to the COVID-19 crisis. This state of emergency means that the population must comply with strict rules such as lockdown (confinement to their homes except for essential trips) and social distancing. The aim of this study was to examine the psychological state of the general population in a sample recruited in Northern Spain. Sociodemographic and psychological data were gathered, assessing variables such as stress, anxiety, and depression. A questionnaire was administered at the beginning of the lockdown and three weeks later. The sample was recruited...",
