    "abstractSummaryId": "In spring 2020, COVID-19 and the ensuing social distancing and stay-at-home orders instigated abrupt changes to employment and educational infrastructure, leading to uncertainty, concern, and stress among United States college students. The media consumption patterns of this and other social groups across the globe were affected, with early evidence suggesting viewers were seeking both pandemic-themed media and reassuring, familiar content. A general increase in media consumption, and increased consumption of specific types of content, may have been due to media use for coping strategies. This paper examines t...",
