      "Hope, optimism, and resilience were all predictive of media use, with the latter two traits moderating responses to stress and anxiety.",
      "The findings give a nuanced portrait of college students' media use during a pandemic-induced shutdown, showing that media use is closely intertwined with well-being in both adaptive and maladaptive patterns."
