    "abstractSummaryId": "Coping with the coronavirus disease (COVID-19) is a significant risk factor for the psychological distress of health workers. Hence, this study explores the relationship between coping strategies used by health and emergency workers in Italy to manage the stress factors related to the COVID-19 emergency, which may result in the risk of developing secondary trauma. We study differences between healthcare (n = 121) and emergency workers (n = 89) in terms of their coping strategies, emergency stress, and secondary trauma, as well as the relationships of these differences to demographic variables and other stress...",
