    "abstractSummaryId": "BACKGROUND: Sleep, physical activity, and diet have been associated with mental health and well-being individually in young adults. However, which of these \"big three\" health behaviors most strongly predicts mental health and well-being, and their higher-order relationships in predictive models, is less known. This study investigated the differential and higher-order associations between sleep, physical activity, and dietary factors as predictors of mental health and well-being in young adults. METHOD: In a cross-sectional survey design, 1,111 young adults (28.4% men) ages 18-25 from New Zealand and the United...",
