    "abstractSummaryId": "INTRODUCTION: Patients who are anxious or depressed after an acute cardiac event are at increased risk of a subsequent event and premature death. It is therefore important to identify these patients early in order to initiate supportive or even preventive measures. In the present study, we report on the prevalence of anxiety and depression during the first 12 months after an acute cardiac event, and the patient characteristics predictive of increased anxiety and depression risk in early and late convalescence. METHODS: We recruited a sample of 911 patients with acute myocardial infarction (AMI), acute coronary...",
