    "abstractSummaryId": "Introduction During the COVID-19 outbreak, many citizens were asked to stay at home in self-quarantine, which can pose a significant challenge with respect to remaining physically active and maintaining mental health. This study aimed to evaluate the prevalence of inadequate physical activity, anxiety, and depression and to explore the relationship of physical activity with anxiety and depression symptoms among Chinese college students during quarantine. Method Using a web-based cross-sectional survey, we collected data from 1,396 Chinese college students. Anxiety and depression were assessed with the Self-Rat...",
