    "abstractSummaryId": "COVID-19 pandemic represents, not only a public physical health emergency, but a mental health serious problem as well. However, little is known about the psychological impact of the quarantine during this pandemic. The aim of this study is to assess the emotional impact of the lockdown measures imposed by the Argentinian government to fight the virus. For this, a survey was distributed on social network. We surveyed the Argentinian general population twice: 2 days after the mandatory quarantine started (time 1), and 2 weeks later (time 2). Anxiety levels were assessed using the State-Trait Anxiety Inventory;...",
