    "abstractSummaryId": "Background Psychological resilience may reduce the impact of psychological distress to some extent. We aimed to investigate the mental health status of the public during the outbreak of coronavirus disease 2019 (COVID-19) and explore the level and related factors of anxiety and depression. Methods From February 8 to March 9, 2020, 3,180 public completed the Zung’s Self-Rating Anxiety Scale (SAS) for anxiety, Zung’s Self-Rating Depression Scale (SDS) for depression, the Connor–Davidson resilience scale (CD-RISC) for psychological resilience, and the Simplified Coping Style Questionnaire (SCSQ) for the attitudes...",
