    "abstractSummaryId": "Introduction: Artificial intelligence (AI) is having a significant impact on people's lives. Despite the benefits associated with this technological advancement, there may be gender-related inequalities in accessing and using AI systems. The present study aimed to test gender differences in factors likely to influence AI adoption, in particular, the moderating role of gender in the relationship between AI anxiety and positive attitudes toward AI. Method: Participants were 335 adults (52.2% women; mean age = 29.96, SD = 13.88) who filled in an online self-report anonymous questionnaire. To test the hypotheses,...",
