    "abstractSummaryId": "On January 30th 2020, the World Health Organization (WHO) declared the COVID-19 pandemic a Public Health Emergency of International Concern (PHEIC). Italy has been one of the most affected countries in the world. To contain further spread of the virus, the Italian government has imposed an unprecedented long-period lockdown for the entire country. This dramatic scenario may have caused a strong psychological distress, with potential negative long-term mental health consequences. The aim of the present study is to report the prevalence of high psychological distress due to the COVID-19 pandemic on the general p...",
