    "abstractSummaryId": "The novel coronavirus disease (COVID-19) has become a global pandemic, causing substantial anxiety. One potential factor in the spread of anxiety in response to a pandemic threat is emotion contagion, the finding that emotional experiences can be socially spread through conscious and unconscious pathways. Some individuals are more susceptible to social contagion effects and may be more likely to experience anxiety and other mental health symptoms in response to a pandemic threat. Therefore, we studied the relationship between emotion contagion and mental health symptoms during the COVID-19 pandemic. We adminis...",
