    "abstractSummaryId": "Introduction: Mindfulness, self-efficacy, and self-regulation play vital roles in shaping the psychological well-being of English as a Foreign Language (EFL) learners. This study investigates the interconnections among these constructs and their implications for the psychological well-being of 527 Chinese EFL learners. Methods: A cross-sectional study was conducted among Chinese EFL learners enrolled in a university in China. Participants were recruited through a non-probability convenience sampling method from English language courses. They completed validated self-report questionnaires assessing mindfulness,...",
