    "abstractSummaryId": "Since March 14, 2020, Spanish citizens have been confined to their homes due to the impact of the COVID-19 pandemic. Participating in musical activities has been associated with reduced anxiety and increased subjective wellbeing. The aim of this study is to analyze how Spanish citizens used music during the lockdown period. We also study perceptions of the impact music has in everyday life, in particular examining the respondents' insights into the effects of listening to music in situations of isolation. The study was conducted using the MUSIVID19 questionnaire administered to a total of 1868 Spanish citizens...",
