    "abstractSummaryId": "Factors such as psychological well-being, sleep quality, and athletic coping skills can influence athletic performance. Mindfulness-based interventions, including mindfulness-based stress reduction (MBSR), have been shown to benefit these factors, suggesting they may, at least indirectly, benefit athletic performance. Moreover, while mindfulness training has been linked to better accuracy in some high-precision sports, whether it can improve non-precision elements of athletic performance is unclear. The objective of this study was to investigate the influence of MBSR on psychological well-being, sleep, athleti...",
