    "abstractSummaryId": "COVID-19 outbreak is a sudden and devastating global pandemic in which the control of the spread is highly dependent on individual reactions, until the development of a vaccine and adequate treatments. Considering that older adults are at high risk for COVID-related medical complications and mortality, the present study focuses on the age-related differences on the adoption of protective behaviors during the initial stages of this outbreak, while accounting for the role of sociodemographic, COVID-related, perceived risk, and psychosocial variables (i.e., anxiety, optimism, fear of death, and social isolation)...",
