    "abstractSummaryId": "INTRODUCTION: Health emergencies, such as epidemics, have detrimental and long-lasting consequences on people's mental health, which are higher during the implementation of strict lockdown measures. Despite several recent psychological researches on the coronavirus disease 2019 (COVID-19) pandemic highlighting that young adults represent a high risk category, no studies specifically focused on young adults' mental health status have been carried out yet. This study aimed to assess and monitor Italian young adults' mental health status during the first 4 weeks of lockdown through the use of a longitudinal panel...",
