    "abstractSummaryId": "Previous research suggested that higher levels of teachers’ self-efficacy tend to be positively related to positive teachers’ emotions (e.g., joy, pride) and negatively to negative teachers’’ emotions (e.g., anger, anxiety). However, these studies predominately relied on cross-sectional design and therefore were unable to test the reciprocal relations between the two constructs. Based on the propositions of social-cognitive theory (Bandura, 1997), TSE may be viewed as an antecedent or as a consequence of emotions. More specifically, TSE may shape emotions since it directs teachers’ attentional, appraisal, and...",
