    "abstractSummaryId": "In Italy, a large outbreak of coronavirus disease 2019 (COVID-19) occurred from 2020 January 30, before the World Health Organization has stated that it is a pandemic. The nationwide quarantine had the desired impact of controlling the epidemic, although had presented many challenges, given its large economic and social costs. Complete adherence to recommendations can potentially decelerate and reduce infectious disease outbreaks. To date, it is not clear how compliant the Italian public has been with voluntary home quarantine, neither which factors have influenced an individual's decision to comply with a qua...",
