    "abstractSummaryId": "The Coronavirus disease 2019 (COVID-19) outbreak generated an unprecedented set of emotional challenges for women diagnosed with breast cancer. In the UK, the pandemic significantly disrupted oncology services as resources were reassigned to care for COVID-19 patients. In addition to service disruptions, many women received a UK Government letter advising them to shield for 12-weeks. We aimed to explore the effect of disruption to scheduled oncology services and the UK Government shielding letter on emotional and cognitive vulnerability. A further aim was to investigate the relationship between COVID-19 relate...",
