    "abstractSummaryId": "Background Physical activity can alleviate negative emotions in college students by enhancing mood and cognitive functions. Yet, the mechanisms underlying these benefits remain unclear. Purpose This study examines the association between physical activity and negative emotions—specifically, depression, anxiety, and stress—in college students. Additionally, we explore the mediating effects of psychological resilience and coping styles to offer theoretical and practical insights for mitigating students’ negative emotions. Methods Using a stratified random sampling approach, a total of 1,380 college students, fro...",
