    "abstractSummaryId": "Background: Coronavirus disease 2019 (COVID-19) has considerably psychologically impacted Chinese college students. Several types of online mental health services were widely implemented for college students during the outbreak. This study investigated the relationship between college students' mental health status and psychological help-seeking behaviour to test the phases-decision-making model (PDM). Methods: A cross-sectional survey was conducted among college students in Guangdong Province using an online platform. In total, 4,164 students were assigned to the ‘counselling group’ or ‘non-counselling group’...",
