    "abstractSummaryId": "Police officer suicide rates hit an all-time high in the province of Ontario, Canada, in 2018. Sadly, this statistic is somewhat unsurprising, as research has shown that police officers suffer from higher rates of mental health disorder diagnoses compared to the general public. One key reason for the elevated levels of suicide and other mental health issues among police officers is believed to stem from the stigma associated with seeking help. In an attempt to address these serious issues, Ontario's police services have begun to create internal peer support programs as a way of supporting their members. The pr...",
