    "abstractSummaryId": "Background Psychiatric nurses need to keep close contact with patients suffering from mental illness. Because of the special nature of their profession, there is an increasing incidence of job burnout among psychiatric nurses. Aim This study examined the relationship between psychiatric nurses’ perceived organizational support, job burnout, and psychological capital. It also investigated the mediating role of psychological capital in the relationship between their perceived organizational support and job burnout. Methods A total of 916 psychiatric nurses were recruited from 6 grade-III mental facilities in Sha...",
