    "abstractSummaryId": "Objective The large-scale epidemic of Coronavirus Disease 2019 (COVID-19) has triggered unprecedented physical and psychological stress on health professionals. This study aimed to investigate the prevalence and risk factors of burnout syndrome, and the relationship between burnout and depressive symptoms among frontline medical staff during the COVID-19 epidemic in China. Methods A total of 606 frontline medical staff were recruited from 133 cities in China using a cross-sectional survey. The Maslach Burnout Inventory (MBI) was used to assess the level of burnout. Depressive symptoms were assessed by the Pati...",
