    "sampleContext": "Detail jumlah & karakteristik partisipan tercantum lengkap pada teks penuh artikel DOI",
    "keyFindings": [
      "Besides, analyses of variance showed that internalizing symptoms of parents and children were significantly higher during the Covid-19 pandemic than before it started.",
      "In addition to showing a direct effect of the pandemic on the psychological health of parents and children, the present results also give a series of important information on how parents perceive, and therefore influence, their children in this period of em...",
      "Our findings thus highlight the urgent need to provide parents with adequate support to take care of their own psychological wellbeing and to help their children coping with the direct and indirect effects of the pandemic."
    ],
