    "abstractSummaryId": "The aim of the present study was to investigate relationships among epidemic risk perception, perceived stress, mental health (depression and anxiety), future time perspective, and confidence in society during the novel coronavirus disease (COVID-19) pandemic in China. Especially, we wonder that whether perceived stress mediates associations between epidemic risk perception and mental health and that whether future time perspective and confidence in society moderate the link between perceived stress and mental health. This cross-sectional study was conducted among 693 Chinese adults aged 18-60 years. The resul...",
